# Слой хранения цитат на Swift: протокол, реализации на SwiftData и в памяти, контрактные тесты

Экраны будут работать с хранилищем через один общий «договор». Им не важно, лежит ли под ним SwiftData или потом GRDB. Чтобы перейти на GRDB, нужно будет написать один новый файл и прогнать на нём те же тесты, что уже есть. Экраны менять не придётся. Отдельно останется перенос накопленных цитат из старой базы в новую: это самостоятельная задача на время перехода.

**Код не компилировался и не запускался.** У меня нет Mac с Xcode, а файлов проекта в этой сессии тоже нет. Решение и код посмотрел независимый ревьюер. Его блокирующие замечания я исправил, но повторный раунд проверки после правок не проводил. Перед тем как забирать код, нужна сборка и прогон тестов на Mac.

## Код

### 1. `QuoteRepository.swift`: договор, который видят экраны

```swift
import Foundation

/// A quote as screens see it: a plain value, independent of the storage engine.
nonisolated struct QuoteItem: Identifiable, Hashable, Sendable {
    let id: UUID
    let text: String
    let bookID: UUID
    let createdAt: Date

    /// The contract's list order: newest first; equal times by id, so the order never jumps
    /// between reloads or between storage engines.
    static func isOrderedBefore(_ lhs: QuoteItem, _ rhs: QuoteItem) -> Bool {
        if lhs.createdAt != rhs.createdAt {
            return lhs.createdAt > rhs.createdAt
        }
        return lhs.id.uuidString > rhs.id.uuidString
    }
}

nonisolated enum QuoteRepositoryError: Error, Equatable {
    /// The text is empty or contains only whitespace.
    case emptyText
    /// No repository was set in the environment: a programming error.
    case notConfigured

    static func checkText(_ text: String) throws {
        if text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            throw QuoteRepositoryError.emptyText
        }
    }
}

/// Quote storage. Screens depend on this protocol only, never on the storage engine.
///
/// Contract for every implementation (checked by `QuoteRepositoryContractTests`):
/// - `quotes(forBook:)` returns the book's quotes in `QuoteItem.isOrderedBefore` order.
/// - `add` throws `QuoteRepositoryError.emptyText` for blank text; otherwise it stores the text
///   as given with a new id and the current time and returns the stored quote. The returned item
///   equals the same quote in later lists (`createdAt` round-trips exactly). `bookID` is not
///   checked against existing books.
/// - `delete` removes every quote with that id; an unknown id does nothing.
/// - A call that starts after another call returned sees its result.
/// - `CancellationError` means the calling task was cancelled: callers ignore it. Any other error
///   is a storage failure: callers show a generic failure and do not inspect it. A failed or
///   cancelled change either completed or left stored data as it was.
/// - The list is not live: callers reload it after their own changes.
nonisolated protocol QuoteRepository: Sendable {
    func quotes(forBook bookID: UUID) async throws -> [QuoteItem]
    @discardableResult
    func add(text: String, toBook bookID: UUID) async throws -> QuoteItem
    func delete(id: UUID) async throws
}
```

### 2. `SwiftDataQuoteRepository.swift`: реализация на текущей базе

```swift
import Foundation
import SwiftData

/// SwiftData implementation.
///
/// Runs on the main actor with its own context and autosave off, so a save or a rollback here
/// touches only this repository's changes, never other screens' unsaved edits. A book's quotes
/// are a small fetch, cheap enough for the main thread. Other code that reads quotes must go
/// through this repository: it does not observe changes made elsewhere.
@MainActor
final class SwiftDataQuoteRepository: QuoteRepository {
    // Held so the container outlives the context; a context does not keep its container alive.
    private let container: ModelContainer
    private let context: ModelContext
    private let now: @Sendable () -> Date

    init(container: ModelContainer, now: @escaping @Sendable () -> Date = { Date() }) {
        self.container = container
        self.context = ModelContext(container)
        self.context.autosaveEnabled = false
        self.now = now
    }

    func quotes(forBook bookID: UUID) throws -> [QuoteItem] {
        let descriptor = FetchDescriptor<Quote>(predicate: #Predicate<Quote> { $0.bookID == bookID })
        return try context.fetch(descriptor)
            .map(Self.item)
            .sorted(by: QuoteItem.isOrderedBefore)
    }

    @discardableResult
    func add(text: String, toBook bookID: UUID) throws -> QuoteItem {
        try QuoteRepositoryError.checkText(text)
        let quote = Quote(id: UUID(), text: text, bookID: bookID, createdAt: now())
        context.insert(quote)
        try saveOrRollback()
        return Self.item(quote)
    }

    func delete(id: UUID) throws {
        let matches = try context.fetch(FetchDescriptor<Quote>(predicate: #Predicate<Quote> { $0.id == id }))
        guard !matches.isEmpty else { return }
        for quote in matches {
            context.delete(quote)
        }
        try saveOrRollback()
    }

    /// The context holds only this repository's changes, so a rollback discards exactly the
    /// failed write.
    private func saveOrRollback() throws {
        do {
            try context.save()
        } catch {
            context.rollback()
            throw error
        }
    }

    private static func item(_ quote: Quote) -> QuoteItem {
        QuoteItem(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt)
    }
}
```

### 3. `InMemoryQuoteRepository.swift`: хранение в памяти для превью и тестов

```swift
import Foundation

/// Keeps quotes in memory, for previews and tests. Data lives as long as the instance.
actor InMemoryQuoteRepository: QuoteRepository {
    private var stored: [QuoteItem]
    private let now: @Sendable () -> Date

    init(quotes: [QuoteItem] = [], now: @escaping @Sendable () -> Date = { Date() }) {
        stored = quotes
        self.now = now
    }

    func quotes(forBook bookID: UUID) -> [QuoteItem] {
        stored.filter { $0.bookID == bookID }.sorted(by: QuoteItem.isOrderedBefore)
    }

    @discardableResult
    func add(text: String, toBook bookID: UUID) throws -> QuoteItem {
        try QuoteRepositoryError.checkText(text)
        let quote = QuoteItem(id: UUID(), text: text, bookID: bookID, createdAt: now())
        stored.append(quote)
        return quote
    }

    func delete(id: UUID) {
        stored.removeAll { $0.id == id }
    }
}
```

### 4. `QuoteRepositoryEnvironment.swift`: как экраны получают хранилище

```swift
import SwiftUI

// Hand-written key instead of @Entry: compiles under both default actor isolation settings.
private nonisolated struct QuoteRepositoryKey: EnvironmentKey {
    static var defaultValue: any QuoteRepository { MissingQuoteRepository() }
}

nonisolated extension EnvironmentValues {
    /// Set once at the app root and in previews.
    var quoteRepository: any QuoteRepository {
        get { self[QuoteRepositoryKey.self] }
        set { self[QuoteRepositoryKey.self] = newValue }
    }
}

/// Default when nobody set a repository: stops in debug builds; in release every call fails,
/// so the screen shows an error instead of crashing or keeping quotes only in memory.
private nonisolated struct MissingQuoteRepository: QuoteRepository {
    func quotes(forBook bookID: UUID) throws -> [QuoteItem] { try fail() }
    func add(text: String, toBook bookID: UUID) throws -> QuoteItem { try fail() }
    func delete(id: UUID) throws { try fail() }

    private func fail() throws -> Never {
        assertionFailure("Set .environment(\\.quoteRepository, ...) at the app root")
        throw QuoteRepositoryError.notConfigured
    }
}
```

### 5. Подключение в корне приложения (добавить к существующему)

```swift
@main
struct SlumpyApp: App {
    private let container: ModelContainer
    private let quoteRepository: SwiftDataQuoteRepository

    init() {
        container = try! ModelContainer(for: Quote.self) // keep the existing container setup
        quoteRepository = SwiftDataQuoteRepository(container: container)
    }

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environment(\.quoteRepository, quoteRepository)
        }
        .modelContainer(container)
    }
}
```

### 6. Пример экрана (показывает, как им пользоваться; вид экрана решаете вы)

```swift
import SwiftUI

struct BookQuotesView: View {
    let bookID: UUID
    @Environment(\.quoteRepository) private var repository
    @State private var quotes: [QuoteItem] = []
    @State private var draft = ""
    @State private var failed = false

    var body: some View {
        List {
            Section {
                TextField("Цитата", text: $draft, axis: .vertical)
                Button("Добавить") {
                    let text = draft
                    Task {
                        await run {
                            try await repository.add(text: text, toBook: bookID)
                            draft = ""
                        }
                    }
                }
                .disabled(draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            Section {
                ForEach(quotes) { quote in
                    Text(quote.text)
                }
                .onDelete { offsets in
                    let ids = offsets.map { quotes[$0].id }
                    Task {
                        await run {
                            for id in ids {
                                try await repository.delete(id: id)
                            }
                        }
                    }
                }
            }
        }
        .task(id: bookID) { await run {} }
        .alert("Что-то пошло не так", isPresented: $failed) {}
    }

    /// Applies a change, then reloads the list from storage.
    private func run(_ change: () async throws -> Void) async {
        do {
            try await change()
            quotes = try await repository.quotes(forBook: bookID)
        } catch is CancellationError {
            // The screen went away; nothing to report.
        } catch {
            failed = true
        }
    }
}

#Preview {
    BookQuotesView(bookID: UUID())
        .environment(\.quoteRepository, InMemoryQuoteRepository())
}
```

### 7. `QuoteRepositoryContractTests.swift`: одни тесты для всех реализаций

```swift
import Foundation
import SwiftData
import Synchronization
import Testing
@testable import Slumpy

@MainActor
struct QuoteRepositoryContractTests {
    enum Engine: CaseIterable, Sendable {
        case swiftData, inMemory
    }

    private func makeRepository(
        _ engine: Engine,
        now: (@Sendable () -> Date)? = nil
    ) throws -> any QuoteRepository {
        let clock = StepClock()
        let now = now ?? { clock.now() }
        switch engine {
        case .swiftData:
            return SwiftDataQuoteRepository(container: try Self.makeContainer(), now: now)
        case .inMemory:
            return InMemoryQuoteRepository(now: now)
        }
    }

    private static func makeContainer() throws -> ModelContainer {
        try ModelContainer(for: Quote.self, configurations: ModelConfiguration(isStoredInMemoryOnly: true))
    }

    @Test(arguments: Engine.allCases)
    func listsOnlyThisBookNewestFirst(_ engine: Engine) async throws {
        let repository = try makeRepository(engine)
        let book = UUID()
        let first = try await repository.add(text: "first", toBook: book)
        try await repository.add(text: "other book", toBook: UUID())
        let second = try await repository.add(text: "second", toBook: book)

        #expect(try await repository.quotes(forBook: book) == [second, first])
    }

    @Test(arguments: Engine.allCases)
    func equalTimesKeepAStableOrder(_ engine: Engine) async throws {
        let sameTime = Date(timeIntervalSince1970: 1_700_000_000)
        let repository = try makeRepository(engine, now: { sameTime })
        let book = UUID()
        let one = try await repository.add(text: "one", toBook: book)
        let two = try await repository.add(text: "two", toBook: book)

        let expected = [one, two].sorted { $0.id.uuidString > $1.id.uuidString }
        #expect(try await repository.quotes(forBook: book) == expected)
        #expect(try await repository.quotes(forBook: book) == expected)
    }

    @Test(arguments: Engine.allCases)
    func storesTextAsGivenAndReturnsWhatIsListed(_ engine: Engine) async throws {
        let repository = try makeRepository(engine)
        let book = UUID()
        let saved = try await repository.add(text: "  Line one\nline two ", toBook: book)

        #expect(saved.text == "  Line one\nline two ")
        #expect(saved.bookID == book)
        #expect(try await repository.quotes(forBook: book) == [saved])
    }

    @Test(arguments: Engine.allCases)
    func rejectsBlankText(_ engine: Engine) async throws {
        let repository = try makeRepository(engine)
        let book = UUID()

        await #expect(throws: QuoteRepositoryError.emptyText) {
            try await repository.add(text: " \n ", toBook: book)
        }
        #expect(try await repository.quotes(forBook: book).isEmpty)
    }

    @Test(arguments: Engine.allCases)
    func deletesOnlyThatQuoteAndIgnoresUnknownID(_ engine: Engine) async throws {
        let repository = try makeRepository(engine)
        let book = UUID()
        let kept = try await repository.add(text: "kept", toBook: book)
        let removed = try await repository.add(text: "removed", toBook: book)

        try await repository.delete(id: removed.id)
        try await repository.delete(id: UUID())

        #expect(try await repository.quotes(forBook: book) == [kept])
    }

    @Test
    func swiftDataWritesReachTheStore() async throws {
        let container = try Self.makeContainer()
        let repository: any QuoteRepository = SwiftDataQuoteRepository(container: container)

        let saved = try await repository.add(text: "saved", toBook: UUID())
        #expect(try ModelContext(container).fetchCount(FetchDescriptor<Quote>()) == 1)

        try await repository.delete(id: saved.id)
        #expect(try ModelContext(container).fetchCount(FetchDescriptor<Quote>()) == 0)
    }
}

/// Returns a later time on every call, so ordering tests do not depend on the real clock.
nonisolated final class StepClock: Sendable {
    private let current = Mutex(Date(timeIntervalSince1970: 1_700_000_000))

    func now() -> Date {
        current.withLock { date in
            defer { date += 1 }
            return date
        }
    }
}
```

## Ключевые решения

- **Экраны получают обычную «карточку цитаты», а не объект базы.** Поэтому в экранах нет ничего от SwiftData и при смене базы им нечего переписывать.
- **Модель `Quote` в базе не переименовывается и не меняется.** Переименование потребовало бы перестройки сохранённых данных, а здесь это не нужно.
- **Одни тесты для всех реализаций.** Будущая версия на GRDB проходит те же проверки: новые сверху, только цитаты своей книги, пустой текст отклоняется, удаление работает. Если она где-то поведёт себя иначе, это покажут тесты, а не пользователи.
- **Порядок не меняется сам по себе.** Если у двух цитат одинаковое время, порядок между ними всё равно фиксированный. Список не будет «прыгать» при обновлении или после смены базы.
- **Сохранение не трогает чужие несохранённые правки.** У хранилища цитат своё рабочее пространство. Если запись не удалась, откатываются только изменения цитаты. Первый вариант такой защиты не давал, это было главное замечание обоих ревью, и оно исправлено.
- **Если забыли подключить хранилище:** при разработке приложение сразу остановится с понятным сообщением. У пользователя экран покажет ошибку, но не упадёт и не станет тихо держать цитаты только в памяти.
- **Пустую цитату сохранить нельзя.** Текст сохраняется ровно как введён, пробелы по краям не обрезаются.

## Допущения

- В модели `Quote` поля `id` и `bookID` имеют тип UUID, все четыре поля обязательные, и у модели есть инициализатор `Quote(id:text:bookID:createdAt:)`. Если это не так, придётся поправить пару строк.
- У одной книги максимум сотни цитат, поэтому их можно читать в основном потоке без задержек.
- Цитаты читают и меняют только через этот слой. Если где-то в приложении цитаты показываются напрямую из базы (например, счётчик цитат на экране книги), это место тоже нужно перевести на слой, иначе оно не увидит изменений.
- Список не обновляется сам: экран перечитывает его после своих изменений. Если позже понадобится живое обновление (например, синхронизация между устройствами), его можно добавить в договор, не ломая экраны.
- Если в приложении удаляют книгу, её цитаты сейчас остаются в базе. Удаление цитат вместе с книгой я не добавлял, потому что его не просили. Это стоит записать на будущее.
- Синхронизации через iCloud и виджетов, читающих цитаты, сейчас нет.

## Проверено и не проверено

- Решение и код прошли независимое ревью, по одному раунду каждое. Найденные проблемы исправлены, повторно после правок не проверялись.
- Сборка и тесты не запускались. Нужно собрать проект на Mac и прогнать тесты, лучше в обоих режимах изоляции акторов (по умолчанию `MainActor` и `nonisolated`): код рассчитан на оба.
- Путь «запись в базу не удалась» тестом не покрыт: такую ошибку SwiftData трудно вызвать специально. Он проверен только ревью.
- Проектные документы (бриф, ADR, записи о ревью) я не сохранял: файлов проекта в этой сессии нет. Их стоит добавить, когда код попадёт в репозиторий.

Готово: ниже весь код, который нужно добавить. Независимое ревью нашло одну серьёзную дыру: ни один тест не проверял, что удаление действительно записывается на диск. Я добавил такой тест и учёл ещё два замечания. Скомпилировать и запустить код здесь было нельзя: нет ни Mac, ни проекта. Перед слиянием его нужно собрать в Xcode и прогнать тесты.

## Как это устроено

Экраны работают только с «договором» `QuoteRepository`. В нём три действия: получить цитаты книги (новые сверху), добавить цитату, удалить цитату. Сейчас этот договор выполняет реализация на SwiftData. При переходе на GRDB пишется вторая реализация того же договора, а экраны не меняются.

**Главные решения:**
- **Экраны получают простую копию цитаты (`QuoteRecord`), а не объект базы.** Поэтому экраны ничего не знают о SwiftData. Сама модель `Quote` не меняется: данные пользователей не трогаем и перенос данных не нужен.
- **Все действия асинхронные.** Сегодня SwiftData работает мгновенно, а GRDB позже сможет работать в фоне, и экраны этого не заметят.
- **SwiftData работает на главном потоке и в общем контексте приложения.** Цитаты маленькие, а так нет известных проблем SwiftData с синхронизацией между потоками.
- **Если сохранение не удалось, изменение отменяется.** Иначе неудачная цитата «висела» бы в памяти и сохранилась бы потом сама.
- **Есть хранилище в памяти** для превью и тестов.
- **Если хранилище забыли подключить, отладочная сборка сразу падает.** Это лучше, чем незаметно терять цитаты.
- **Одни и те же тесты проверяют обе реализации.** Будущая реализация на GRDB должна будет пройти их же.

## Код

### `QuoteRepository.swift`
```swift
import Foundation

/// A saved quote as screens see it. Independent of the storage engine.
nonisolated struct QuoteRecord: Identifiable, Hashable, Sendable {
    let id: UUID
    let text: String
    let bookID: UUID
    let createdAt: Date

    /// Trims surrounding whitespace; a quote with no visible text is rejected.
    static func normalizedText(_ raw: String) throws -> String {
        let text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { throw QuoteRepositoryError.emptyText }
        return text
    }
}

nonisolated enum QuoteRepositoryError: Error, Equatable {
    case emptyText
    case notConfigured
}

/// Quote storage for screens. Screens depend only on this protocol, so the storage engine
/// (SwiftData today) can be replaced without touching them.
nonisolated protocol QuoteRepository: Sendable {
    /// Quotes of one book, newest first.
    func quotes(forBook bookID: UUID) async throws -> [QuoteRecord]
    /// Saves a new quote and returns it as stored. Throws `QuoteRepositoryError.emptyText` for blank text.
    func addQuote(text: String, toBook bookID: UUID) async throws -> QuoteRecord
    /// Deletes a quote. Deleting a quote that does not exist is not an error.
    func deleteQuote(id: UUID) async throws
}
```

### `SwiftDataQuoteRepository.swift`
```swift
import Foundation
import SwiftData

/// SwiftData implementation. Uses the container's main context on the main actor: quote lists
/// are small, and one shared context avoids cross-context merging with any remaining `@Query`.
@MainActor
final class SwiftDataQuoteRepository: QuoteRepository {
    private let container: ModelContainer
    private let now: @Sendable () -> Date

    private var context: ModelContext { container.mainContext }

    init(modelContainer: ModelContainer, now: @escaping @Sendable () -> Date = { .now }) {
        container = modelContainer
        self.now = now
    }

    func quotes(forBook bookID: UUID) async throws -> [QuoteRecord] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try context.fetch(descriptor).map(Self.record(from:))
    }

    func addQuote(text: String, toBook bookID: UUID) async throws -> QuoteRecord {
        let text = try QuoteRecord.normalizedText(text)
        let quote = Quote(id: UUID(), text: text, bookID: bookID, createdAt: now())
        try commit { context.insert(quote) }
        return Self.record(from: quote)
    }

    func deleteQuote(id: UUID) async throws {
        let quoteID = id
        let descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == quoteID })
        let matches = try context.fetch(descriptor)
        guard !matches.isEmpty else { return }
        try commit { matches.forEach { context.delete($0) } }
    }

    /// Applies one change and saves it; on failure undoes it so memory matches disk.
    private func commit(_ change: () -> Void) throws {
        // Save unrelated pending edits first, so the rollback below undoes only this change.
        if context.hasChanges { try context.save() }
        change()
        do {
            try context.save()
        } catch {
            context.rollback()
            throw error
        }
    }

    private static func record(from quote: Quote) -> QuoteRecord {
        QuoteRecord(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt)
    }
}
```

