    /// Quote storage for screens. The app sets the real one at the root; previews set an
    /// `InMemoryQuoteRepository`.
    nonisolated var quoteRepository: any QuoteRepository {
        get { self[QuoteRepositoryKey.self] }
        set { self[QuoteRepositoryKey.self] = newValue }
    }
}

private nonisolated struct QuoteRepositoryKey: EnvironmentKey {
    static let defaultValue: any QuoteRepository = MissingQuoteRepository()
}

/// Default when nobody injected a repository: fails loudly in debug builds instead of silently
/// keeping quotes in memory and losing them.
private nonisolated struct MissingQuoteRepository: QuoteRepository {
    func quotes(forBook bookID: UUID) async throws -> [QuoteRecord] { try fail() }
    func addQuote(text: String, toBook bookID: UUID) async throws -> QuoteRecord { try fail() }
    func deleteQuote(id: UUID) async throws { try fail() }

    private func fail<T>() throws -> T {
        assertionFailure("quoteRepository is not set in the environment")
        throw QuoteRepositoryError.notConfigured
    }
}
