```swift
import SwiftUI

struct BookQuotesView: View {
    let bookID: UUID

    @Environment(\.quoteRepository) private var repository
    @State private var quotes: [QuoteRecord] = []
    @State private var draft = ""
    @State private var isSaving = false
    @State private var showsError = false

    var body: some View {
        List {
            Section {
                TextField("Новая цитата", text: $draft, axis: .vertical)
                Button("Добавить") { Task { await add() } }
                    .disabled(isSaving || draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            Section {
                ForEach(quotes) { Text($0.text) }
                    .onDelete { offsets in
                        let ids = offsets.map { quotes[$0].id }
                        Task { await delete(ids) }
                    }
            }
        }
        .task(id: bookID) { await load() }
        .alert("Не получилось", isPresented: $showsError) {}
    }

    private func load() async {
        do {
            let loaded = try await repository.quotes(forBook: bookID)
            guard !Task.isCancelled else { return }
            quotes = loaded
        } catch is CancellationError {
        } catch {
            showsError = true
        }
    }

    private func add() async {
        let text = draft
        isSaving = true
        defer { isSaving = false }
        do {
            let quote = try await repository.addQuote(text: text, toBook: bookID)
            quotes.insert(quote, at: 0)
            if draft == text { draft = "" }
        } catch {
            showsError = true
        }
    }

    private func delete(_ ids: [UUID]) async {
        quotes.removeAll { ids.contains($0.id) }
        do {
            for id in ids { try await repository.deleteQuote(id: id) }
        } catch {
            showsError = true
            await load()
        }
    }
}

