```swift
import Foundation
import SwiftData
import Synchronization
import Testing
@testable import Slumpy

nonisolated enum QuoteBackend: CaseIterable, Sendable {
    case swiftData, inMemory
}

/// Returns a later date on every call, so ordering tests never depend on real time.
nonisolated final class StepClock: Sendable {
    private let last = Mutex(Date(timeIntervalSinceReferenceDate: 0))

    func now() -> Date {
        last.withLock { date in
            date += 1
            return date
        }
    }
}

@MainActor
struct QuoteRepositoryContractTests {
    @Test(arguments: QuoteBackend.allCases)
    func listsOnlyThisBookNewestFirst(_ backend: QuoteBackend) async throws {
        let repository = try makeRepository(backend)
        let book = UUID()
        let first = try await repository.addQuote(text: "First", toBook: book)
        let second = try await repository.addQuote(text: "Second", toBook: book)
        _ = try await repository.addQuote(text: "Elsewhere", toBook: UUID())

        let quotes = try await repository.quotes(forBook: book)
        #expect(quotes == [second, first])
    }

    @Test(arguments: QuoteBackend.allCases)
    func addTrimsText(_ backend: QuoteBackend) async throws {
        let repository = try makeRepository(backend)
        let book = UUID()

        let quote = try await repository.addQuote(text: "  To be.\n", toBook: book)

        #expect(quote.text == "To be.")
        let quotes = try await repository.quotes(forBook: book)
        #expect(quotes == [quote])
    }

    @Test(arguments: QuoteBackend.allCases)
    func rejectsBlankText(_ backend: QuoteBackend) async throws {
        let repository = try makeRepository(backend)
        let book = UUID()

        await #expect(throws: QuoteRepositoryError.emptyText) {
            try await repository.addQuote(text: " \n ", toBook: book)
        }
        let quotes = try await repository.quotes(forBook: book)
        #expect(quotes.isEmpty)
    }

    @Test(arguments: QuoteBackend.allCases)
    func deleteRemovesOnlyThatQuote(_ backend: QuoteBackend) async throws {
        let repository = try makeRepository(backend)
        let book = UUID()
        let kept = try await repository.addQuote(text: "Kept", toBook: book)
        let removed = try await repository.addQuote(text: "Removed", toBook: book)

        try await repository.deleteQuote(id: removed.id)

        let quotes = try await repository.quotes(forBook: book)
        #expect(quotes == [kept])
    }

    @Test(arguments: QuoteBackend.allCases)
    func deletingUnknownQuoteIsNoOp(_ backend: QuoteBackend) async throws {
        let repository = try makeRepository(backend)
        let book = UUID()
        let quote = try await repository.addQuote(text: "Stays", toBook: book)

        try await repository.deleteQuote(id: UUID())

        let quotes = try await repository.quotes(forBook: book)
        #expect(quotes == [quote])
    }

    @Test
    func swiftDataSavesAddAndDeleteToStore() async throws {
        let container = try makeContainer()
        let repository = SwiftDataQuoteRepository(modelContainer: container)

        let quote = try await repository.addQuote(text: "Saved", toBook: UUID())
        #expect(try savedIDs(in: container) == [quote.id])

        try await repository.deleteQuote(id: quote.id)
        #expect(try savedIDs(in: container).isEmpty)
    }

    // MARK: - Helpers

    private func makeRepository(_ backend: QuoteBackend) throws -> any QuoteRepository {
        let clock = StepClock()
        switch backend {
        case .swiftData:
            return SwiftDataQuoteRepository(modelContainer: try makeContainer(), now: { clock.now() })
        case .inMemory:
            return InMemoryQuoteRepository(now: { clock.now() })
        }
    }

    private func makeContainer() throws -> ModelContainer {
        let config = ModelConfiguration(UUID().uuidString, isStoredInMemoryOnly: true)
        return try ModelContainer(for: Quote.self, configurations: config)
    }

    /// A fresh context sees only what was saved, not the main context's pending changes.
    private func savedIDs(in container: ModelContainer) throws -> [UUID] {
        try ModelContext(container).fetch(FetchDescriptor<Quote>()).map(\.id)
    }
