**`BookCover.swift`**

```swift
import Foundation
import SwiftData

@Model
final class BookCoverThumbnail {
    /// New for every photo, so caches keyed by it never show a replaced cover.
    var id: UUID = UUID()
    var data: Data = Data()
    var book: Book?

    init(data: Data) {
        self.data = data
    }
}

@Model
final class BookCoverImage {
    var id: UUID = UUID()
    @Attribute(.externalStorage) var data: Data = Data()
    var book: Book?

    init(data: Data) {
        self.data = data
    }
}

extension Book {
    /// Swaps in a new cover and deletes the old one. The caller saves the context.
    func replaceCover(with cover: CoverImageProcessor.Output, in context: ModelContext) {
        if let coverThumbnail { context.delete(coverThumbnail) }
        if let coverImage { context.delete(coverImage) }
        let thumbnail = BookCoverThumbnail(data: cover.thumbnail)
        let image = BookCoverImage(data: cover.image)
        context.insert(thumbnail)
        context.insert(image)
        coverThumbnail = thumbnail
        coverImage = image
    }
}
```

**`CoverImageProcessor.swift`**

```swift
import UIKit

/// Turns a camera photo into the stored JPEGs and decodes them for display.
/// Everything here runs off the main actor: resampling a 12 MP photo takes tens of milliseconds.
nonisolated enum CoverImageProcessor {
    nonisolated struct Output: Sendable {
        let image: Data
        let thumbnail: Data
    }

    /// Long side of the stored cover: sharp on the book screen at 3x.
    static let imageMaxPixelSide: CGFloat = 1200
    /// Long side of the list thumbnail: fills the largest (64 pt wide) row cover at 3x.
    static let thumbnailMaxPixelSide: CGFloat = 300

    @concurrent
    static func makeCover(from photo: UIImage) async -> Output? {
        guard photo.size.width > 0, photo.size.height > 0 else { return nil }
        let resized = resize(photo, maxPixelSide: imageMaxPixelSide)
        guard let image = resized.jpegData(compressionQuality: 0.8),
              let thumbnail = resize(resized, maxPixelSide: thumbnailMaxPixelSide).jpegData(compressionQuality: 0.7)
        else { return nil }
        return Output(image: image, thumbnail: thumbnail)
    }

    /// Decodes JPEG bytes into a bitmap ready to draw, so scrolling never decodes on the main thread.
    @concurrent
    static func decode(_ data: Data) async -> UIImage? {
        UIImage(data: data)?.preparingForDisplay()
    }

    private static func resize(_ photo: UIImage, maxPixelSide: CGFloat) -> UIImage {
        let width = photo.size.width * photo.scale
        let height = photo.size.height * photo.scale
        let ratio = min(1, maxPixelSide / max(width, height))
        let size = CGSize(width: (width * ratio).rounded(), height: (height * ratio).rounded())
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        // draw(in:) applies the photo's orientation, so the result is always upright
        // and carries no EXIF metadata.
        return UIGraphicsImageRenderer(size: size, format: format).image { _ in
            photo.draw(in: CGRect(origin: .zero, size: size))
        }
    }
}
```

