import AVFoundation
import SwiftUI
import UIKit

/// Decoded library thumbnails keyed by `BookCoverThumbnail.id`.
/// NSCache also empties itself when the system is short on memory.
@MainActor
enum CoverThumbnailCache {
    private static let storage: NSCache<NSUUID, UIImage> = {
        let cache = NSCache<NSUUID, UIImage>()
        cache.countLimit = 120 // about 270 KB per decoded thumbnail, so ~32 MB at most
        return cache
    }()

    static func image(for id: UUID) -> UIImage? {
        storage.object(forKey: id as NSUUID)
    }

    static func insert(_ image: UIImage, for id: UUID) {
        storage.setObject(image, forKey: id as NSUUID)
    }
}

/// A cover in a 2:3 frame, or a book icon when there is no photo yet.
