/// Small cover for a library row.
struct BookCoverThumbnailView: View {
    let book: Book
    @ScaledMetric(relativeTo: .body) private var width: CGFloat = 40
    @State private var decoded: (id: UUID, image: UIImage)?

    var body: some View {
        let thumbnail = book.coverThumbnail
        CoverArtwork(image: image(for: thumbnail?.id))
            .frame(width: min(width, 64))
            .accessibilityHidden(true) // the row already reads the title
            .task(id: thumbnail?.id) { await load(thumbnail) }
    }

    /// Checks the cache synchronously so a reused row shows its cover without a placeholder flash.
    private func image(for id: UUID?) -> UIImage? {
        guard let id else { return nil }
        if let decoded, decoded.id == id { return decoded.image }
        return CoverThumbnailCache.image(for: id)
    }

    private func load(_ thumbnail: BookCoverThumbnail?) async {
        guard let thumbnail, image(for: thumbnail.id) == nil else { return }
        let id = thumbnail.id
        guard let image = await CoverImageProcessor.decode(thumbnail.data) else { return }
        CoverThumbnailCache.insert(image, for: id)
        decoded = (id, image)
    }
}

/// Cover on the book screen, with the button that opens the camera.
struct BookCoverSection: View {
    let book: Book
    @Environment(\.modelContext) private var modelContext
    @Environment(\.openURL) private var openURL
    @State private var image: UIImage?
    @State private var isShowingCamera = false
    @State private var isProcessing = false
    @State private var isShowingCameraDenied = false
    @State private var isShowingCameraRestricted = false
    @State private var isShowingSaveError = false

    var body: some View {
        let cover = book.coverImage
        VStack(spacing: 12) {
            // Keeps the previous image until the new one is decoded, so a retake never flashes the icon.
            CoverArtwork(image: cover == nil ? nil : image, placeholderFont: .system(size: 44))
                .frame(maxWidth: 200)
                .overlay {
                    if isProcessing { ProgressView() }
                }
                .accessibilityElement(children: .ignore)
                .accessibilityLabel(cover == nil ? "Нет обложки" : "Обложка книги")
                .accessibilityAddTraits(.isImage)

            if UIImagePickerController.isSourceTypeAvailable(.camera) {
                Button(cover == nil ? "Сфотографировать обложку" : "Переснять обложку", systemImage: "camera") {
                    openCamera()
                }
                .disabled(isProcessing)
            }
        }
        .task(id: cover?.id) { await load(cover) }
        .fullScreenCover(isPresented: $isShowingCamera) {
            CameraPicker { photo in
                isShowingCamera = false
                if let photo { save(photo) }
            }
            .ignoresSafeArea()
        }
        .alert("Нет доступа к камере", isPresented: $isShowingCameraDenied) {
            Button("Открыть настройки") {
                if let url = URL(string: UIApplication.openSettingsURLString) { openURL(url) }
            }
            Button("Отмена", role: .cancel) {}
        } message: {
            Text("Разрешите Slumpy доступ к камере в Настройках, чтобы сфотографировать обложку.")
        }
        .alert("Камера недоступна", isPresented: $isShowingCameraRestricted) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("Камера на этом устройстве ограничена Экранным временем или профилем организации.")
        }
        .alert("Не удалось сохранить обложку", isPresented: $isShowingSaveError) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("Попробуйте сфотографировать ещё раз.")
        }
    }

    private func openCamera() {
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .authorized:
            isShowingCamera = true
        case .notDetermined:
            // Ask first, so a "Don't Allow" never leaves the user on a blank camera screen.
            Task {
                if await AVCaptureDevice.requestAccess(for: .video) {
                    isShowingCamera = true
                }
            }
        case .restricted:
            isShowingCameraRestricted = true
        default:
            isShowingCameraDenied = true
        }
    }

    private func save(_ photo: UIImage) {
        isProcessing = true
        // Not tied to the view's lifetime: the photo is saved even if the user leaves the screen.
        Task {
            defer { isProcessing = false }
            guard let cover = await CoverImageProcessor.makeCover(from: photo) else {
                isShowingSaveError = true
                return
            }
            book.replaceCover(with: cover, in: modelContext)
            do {
                try modelContext.save()
            } catch {
                // Otherwise autosave could later store the cover the alert says was not saved.
                modelContext.rollback()
                isShowingSaveError = true
            }
        }
    }

    private func load(_ cover: BookCoverImage?) async {
        guard let cover else {
            image = nil
            return
        }
        let decoded = await CoverImageProcessor.decode(cover.data)
        guard !Task.isCancelled else { return }
        image = decoded
    }
}
