### `Book+Cover.swift`

```swift
import SwiftData

extension Book {
    func replaceCover(with images: CoverImageProcessor.Output, in context: ModelContext) throws {
        let newCover = BookCover(thumbnailData: images.thumbnailData, imageData: images.imageData)
        context.insert(newCover)
        let oldCover = cover
        cover = newCover
        if let oldCover { context.delete(oldCover) }
        try saveOrRollBack(context)
    }

    func removeCover(in context: ModelContext) throws {
        guard let oldCover = cover else { return }
        cover = nil
        context.delete(oldCover)
        try saveOrRollBack(context)
    }

    /// A failed save (usually a full disk) must not leave the change on screen or let autosave retry it silently.
    private func saveOrRollBack(_ context: ModelContext) throws {
        do {
            try context.save()
        } catch {
            context.rollback()
            throw error
        }
    }
}
