### `CoverImageProcessor.swift`

```swift
import UIKit

/// Turns a full-size camera photo into the two JPEGs we store. The 12 MP original is never persisted.
nonisolated enum CoverImageProcessor {
    nonisolated struct Output: Sendable {
        let imageData: Data
        let thumbnailData: Data
    }

    /// Sharp at 3x for a cover about 400 pt tall on the book screen.
    static let imageMaxPixels: CGFloat = 1200
    /// Sharp at 3x for a 60 pt wide list cover, which covers large Dynamic Type sizes.
    static let thumbnailMaxPixels: CGFloat = 270
    static let jpegQuality: CGFloat = 0.75

    @concurrent
    static func makeCover(from photo: UIImage) async -> Output? {
        let image = downscaled(photo, maxPixels: imageMaxPixels)
        let thumbnail = downscaled(image, maxPixels: thumbnailMaxPixels)
        guard let imageData = image.jpegData(compressionQuality: jpegQuality),
              let thumbnailData = thumbnail.jpegData(compressionQuality: jpegQuality) else { return nil }
        return Output(imageData: imageData, thumbnailData: thumbnailData)
    }

    /// Redraws the photo upright (applying its orientation) at 1x, never upscaling.
    private static func downscaled(_ image: UIImage, maxPixels: CGFloat) -> UIImage {
        let pixelWidth = image.size.width * image.scale
        let pixelHeight = image.size.height * image.scale
        let factor = min(1, maxPixels / max(pixelWidth, pixelHeight))
        let size = CGSize(width: (pixelWidth * factor).rounded(), height: (pixelHeight * factor).rounded())
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        // 8-bit sRGB keeps memory predictable; the default may pick a 16-bit extended-range context.
        format.preferredRange = .standard
        return UIGraphicsImageRenderer(size: size, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: size))
        }
    }
}
```

### `CoverImageCache.swift`

```swift
import UIKit

/// Decoded list thumbnails keyed by `BookCover.id`. NSCache evicts entries under memory pressure.
@MainActor
final class CoverImageCache {
    static let shared = CoverImageCache()

    private let thumbnails = NSCache<NSUUID, UIImage>()

    private init() {
        thumbnails.totalCostLimit = 40 * 1024 * 1024
    }

    func thumbnail(for coverID: UUID) -> UIImage? {
        thumbnails.object(forKey: coverID as NSUUID)
    }

    func insertThumbnail(_ image: UIImage, for coverID: UUID) {
        let cost = image.cgImage.map { $0.bytesPerRow * $0.height } ?? 0
        thumbnails.setObject(image, forKey: coverID as NSUUID, cost: cost)
    }
}
```

### `BookCoverView.swift`: показ обложки в списке и на экране книги

```swift
import SwiftUI
import UIKit

struct BookCoverView: View {
    enum Variant { case thumbnail, full }

    let book: Book
    let variant: Variant

    @State private var loaded: LoadedImage?

    var body: some View {
        let coverID = book.cover?.id
        let shownImage = image(for: coverID)
        Group {
            if let shownImage {
                switch variant {
                case .thumbnail:
                    placeholder.overlay { Image(uiImage: shownImage).resizable().scaledToFill() }
                case .full:
                    Image(uiImage: shownImage).resizable().scaledToFit()
                }
            } else {
                placeholder.overlay { Image(systemName: "book.closed").foregroundStyle(.secondary) }
            }
        }
        .clipShape(.rect(cornerRadius: variant == .thumbnail ? 4 : 12))
        .accessibilityHidden(variant == .thumbnail)
        .accessibilityLabel(coverID == nil ? "Нет обложки" : "Обложка книги «\(book.title)»")
        .task(id: coverID) { await load() }
    }

    private var placeholder: some View {
        Rectangle().fill(.quaternary).aspectRatio(2 / 3, contentMode: .fit)
    }

    private func image(for coverID: UUID?) -> UIImage? {
        guard let coverID else { return nil }
        if let loaded, loaded.coverID == coverID { return loaded.image }
        return variant == .thumbnail ? CoverImageCache.shared.thumbnail(for: coverID) : nil
    }

    /// Decodes off the main thread so scrolling 500+ books stays smooth.
    private func load() async {
        guard let cover = book.cover, image(for: cover.id) == nil else { return }
        let coverID = cover.id
        let data = variant == .thumbnail ? cover.thumbnailData : cover.imageData
        guard let decoded = await UIImage(data: data)?.byPreparingForDisplay(), !Task.isCancelled else { return }
        if variant == .thumbnail { CoverImageCache.shared.insertThumbnail(decoded, for: coverID) }
        loaded = LoadedImage(coverID: coverID, image: decoded)
    }

    private struct LoadedImage {
        let coverID: UUID
        let image: UIImage
    }
}
