### `BookCoverSection.swift`: вставить на экран книги

```swift
import AVFoundation
import SwiftUI
import UIKit

struct BookCoverSection: View {
    let book: Book

    @Environment(\.openURL) private var openURL
    @State private var isCameraPresented = false
    @State private var cameraAccessProblem: CameraAccessProblem?
    @State private var isRemoveConfirmationPresented = false
    @State private var isErrorAlertPresented = false
    @State private var isProcessing = false

    var body: some View {
        VStack(spacing: 12) {
            BookCoverView(book: book, variant: .full)
                .frame(maxWidth: 240, maxHeight: 360)
                .overlay {
                    if isProcessing { ProgressView().controlSize(.large) }
                }

            if UIImagePickerController.isSourceTypeAvailable(.camera) {
                Button(book.cover == nil ? "Сфотографировать обложку" : "Переснять обложку", systemImage: "camera") {
                    openCamera()
                }
                .disabled(isProcessing)
            }

            if book.cover != nil {
                Button("Удалить обложку", systemImage: "trash", role: .destructive) {
                    isRemoveConfirmationPresented = true
                }
                .disabled(isProcessing)
            }
        }
        .fullScreenCover(isPresented: $isCameraPresented) {
            CameraPicker { photo in
                isCameraPresented = false
                if let photo {
                    Task { await saveCover(from: photo) }
                }
            }
            .ignoresSafeArea()
        }
        .confirmationDialog("Удалить обложку?", isPresented: $isRemoveConfirmationPresented, titleVisibility: .visible) {
            Button("Удалить", role: .destructive) { removeCover() }
        }
        .alert(
            "Нет доступа к камере",
            isPresented: Binding(
                get: { cameraAccessProblem != nil },
                set: { if !$0 { cameraAccessProblem = nil } }
            ),
            presenting: cameraAccessProblem
        ) { problem in
            if problem == .denied {
                Button("Открыть настройки") {
                    if let url = URL(string: UIApplication.openSettingsURLString) { openURL(url) }
                }
                Button("Отмена", role: .cancel) {}
            } else {
                Button("Понятно", role: .cancel) {}
            }
        } message: { problem in
            if problem == .denied {
                Text("Разрешите доступ к камере в Настройках, чтобы сфотографировать обложку.")
            } else {
                Text("Камера отключена ограничениями на этом устройстве, например Экранным временем.")
            }
        }
        .alert("Не удалось сохранить обложку", isPresented: $isErrorAlertPresented) {
            Button("OK", role: .cancel) {}
        }
    }

    private enum CameraAccessProblem { case denied, restricted }

    private func openCamera() {
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .denied: cameraAccessProblem = .denied
        case .restricted: cameraAccessProblem = .restricted
        // .notDetermined: presenting the picker shows the system permission prompt.
        default: isCameraPresented = true
        }
    }

    private func saveCover(from photo: UIImage) async {
        isProcessing = true
        defer { isProcessing = false }
        guard let images = await CoverImageProcessor.makeCover(from: photo) else {
            isErrorAlertPresented = true
            return
        }
        // The book may have been deleted while the photo was processed.
        guard let context = book.modelContext else { return }
        do {
            try book.replaceCover(with: images, in: context)
        } catch {
            isErrorAlertPresented = true
        }
    }

    private func removeCover() {
        guard let context = book.modelContext else { return }
        do {
            try book.removeCover(in: context)
        } catch {
            isErrorAlertPresented = true
        }
    }
}
