### 1. `ReadingHistoryCSV.swift`: формирование CSV

```swift
import Foundation

/// One exported line. A plain value type, so the file can be built off the main actor
/// even if `ReadingSession` is a SwiftData model.
nonisolated struct ReadingHistoryRow: Sendable, Equatable {
    let startedAt: Date
    let duration: TimeInterval
    let timeZoneIdentifier: String
    let bookTitle: String
    let bookAuthor: String
}

nonisolated enum ReadingHistoryCSV {
    enum Delimiter: String, Sendable {
        case comma = ","
        case semicolon = ";"
    }

    /// Excel splits a double-clicked CSV by the system list separator: ";" in regions with a
    /// decimal comma (ru, de, fr, ...), "," elsewhere. Numbers detects either.
    static func delimiter(for locale: Locale) -> Delimiter {
        locale.decimalSeparator == "," ? .semicolon : .comma
    }

    static var defaultHeader: [String] {
        [
            String(localized: "readingHistory.csv.startedAt", defaultValue: "Дата и время начала"),
            String(localized: "readingHistory.csv.minutes", defaultValue: "Длительность, мин"),
            String(localized: "readingHistory.csv.title", defaultValue: "Название"),
            String(localized: "readingHistory.csv.author", defaultValue: "Автор"),
        ]
    }

    /// UTF-8 with BOM: without the BOM Excel reads Cyrillic as mojibake.
    static func makeData(rows: [ReadingHistoryRow], delimiter: Delimiter, header: [String]) -> Data {
        var data = Data([0xEF, 0xBB, 0xBF])
        data.append(Data(makeText(rows: rows, delimiter: delimiter, header: header).utf8))
        return data
    }

    /// RFC 4180: CRLF line endings, a field is quoted when it contains the delimiter,
    /// a quote, or a line break; quotes inside are doubled.
    static func makeText(rows: [ReadingHistoryRow], delimiter: Delimiter, header: [String]) -> String {
        var lines = [header.map { field($0, delimiter: delimiter) }.joined(separator: delimiter.rawValue)]
        for row in rows {
            let fields = [
                startDateText(row.startedAt, timeZoneIdentifier: row.timeZoneIdentifier),
                String(wholeMinutes(row.duration)),
                field(row.bookTitle, delimiter: delimiter),
                field(row.bookAuthor, delimiter: delimiter),
            ]
            lines.append(fields.joined(separator: delimiter.rawValue))
        }
        return lines.joined(separator: "\r\n") + "\r\n"
    }

    static func field(_ value: String, delimiter: Delimiter) -> String {
        var text = value
        // A cell starting with = + - @ runs as a formula in Excel; a leading apostrophe keeps it text.
        if let first = text.first, ["=", "+", "-", "@", "\t", "\r"].contains(first) {
            text = "'" + text
        }
        let needsQuotes = text.contains(delimiter.rawValue)
            || text.contains("\"") || text.contains("\n") || text.contains("\r")
        guard needsQuotes else { return text }
        return "\"" + text.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    /// "2026-10-27 21:30" in the zone where the session happened. Excel and Numbers recognise
    /// this form as a date and time in any region.
    static func startDateText(_ date: Date, timeZoneIdentifier: String) -> String {
        let timeZone = TimeZone(identifier: timeZoneIdentifier) ?? .current
        return date.formatted(dateTimeStyle(timeZone: timeZone))
    }

    static func dateTimeStyle(timeZone: TimeZone) -> Date.VerbatimFormatStyle {
        Date.VerbatimFormatStyle(
            format: "\(year: .defaultDigits)-\(month: .twoDigits)-\(day: .twoDigits) \(hour: .twoDigits(clock: .twentyFourHour, hourCycle: .zeroBased)):\(minute: .twoDigits)",
            timeZone: timeZone,
            calendar: Calendar(identifier: .gregorian)
        )
    }

    /// Whole minutes, rounded to nearest. Integers avoid the decimal comma vs point problem.
    static func wholeMinutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int(exactly: (duration / 60).rounded()) ?? 0
    }
}
```

### 2. `ReadingHistoryExport.swift`: файл для ShareLink

```swift
import CoreTransferable
import Foundation
import UniformTypeIdentifiers

/// The file is written only when the user picks a share target, not on every screen render.
nonisolated struct ReadingHistoryExport: Transferable, Sendable {
    let rows: [ReadingHistoryRow]
    let delimiter: ReadingHistoryCSV.Delimiter
    let header: [String]
    let fileName: String

    init(rows: [ReadingHistoryRow], locale: Locale = .current, now: Date = .now) {
        self.rows = rows.sorted { $0.startedAt < $1.startedAt }
        self.delimiter = ReadingHistoryCSV.delimiter(for: locale)
        self.header = ReadingHistoryCSV.defaultHeader
        let day = now.formatted(
            Date.VerbatimFormatStyle(
                format: "\(year: .defaultDigits)-\(month: .twoDigits)-\(day: .twoDigits)",
                timeZone: .current,
                calendar: Calendar(identifier: .gregorian)
            )
        )
        self.fileName = String(
            localized: "readingHistory.csv.fileName",
            defaultValue: "История чтения \(day)"
        ) + ".csv"
    }

    static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(exportedContentType: .commaSeparatedText) { export in
            SentTransferredFile(try export.writeTemporaryFile())
        }
    }

    /// A fresh folder per export, so the readable file name never collides.
    /// The system purges the temporary directory itself.
    func writeTemporaryFile() throws -> URL {
        let directory = FileManager.default.temporaryDirectory
            .appending(path: "ReadingHistoryExport", directoryHint: .isDirectory)
            .appending(path: UUID().uuidString, directoryHint: .isDirectory)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let url = directory.appending(path: fileName, directoryHint: .notDirectory)
        try ReadingHistoryCSV.makeData(rows: rows, delimiter: delimiter, header: header)
            .write(to: url, options: .atomic)
        return url
    }
}
```

