import CoreTransferable
import Foundation
import UniformTypeIdentifiers

/// Reading history as a CSV file that opens correctly in Excel and Numbers.
/// The file is written only when the user picks a share destination.
nonisolated struct ReadingHistoryCSV: Transferable, Sendable {
    /// Sendable snapshot of one reading session.
    struct Row: Sendable {
        var startedAt: Date
        var timeZoneIdentifier: String
        var duration: TimeInterval
        var bookTitle: String
        var bookAuthor: String
    }

    let rows: [Row]
    let delimiter: Character
    let exportDate: Date

    init(
        rows: [Row],
        delimiter: Character = Self.defaultDelimiter(for: .current),
        exportDate: Date = .now
    ) {
        self.rows = rows.sorted { $0.startedAt < $1.startedAt }
        self.delimiter = delimiter
        self.exportDate = exportDate
    }

    @MainActor
    init(sessions: [ReadingSession]) {
        self.init(rows: sessions.map {
            Row(
                startedAt: $0.startedAt,
                timeZoneIdentifier: $0.timeZoneIdentifier,
                duration: $0.duration,
                bookTitle: $0.bookTitle,
                bookAuthor: $0.bookAuthor
            )
        })
    }

    static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(exportedContentType: .commaSeparatedText) { csv in
            SentTransferredFile(try csv.writeTemporaryFile())
        }
    }

    // MARK: - Content

    /// Excel splits columns by the system list separator: ";" in regions with a decimal comma
    /// (Russia, most of Europe), "," elsewhere. Numbers detects either.
    static func defaultDelimiter(for locale: Locale) -> Character {
        locale.decimalSeparator == "," ? ";" : ","
    }

    var text: String {
        let separator = String(delimiter)
        let header = [
            String(localized: "csvExport.header.start", defaultValue: "Начало"),
            String(localized: "csvExport.header.minutes", defaultValue: "Длительность, мин"),
            String(localized: "csvExport.header.title", defaultValue: "Книга"),
            String(localized: "csvExport.header.author", defaultValue: "Автор"),
        ].map(Self.quoted)

        var lines = [header.joined(separator: separator)]
        for row in rows {
            let timeZone = TimeZone(identifier: row.timeZoneIdentifier) ?? .current
            lines.append([
                Self.format(row.startedAt, in: timeZone, withTime: true),
                String(Self.minutes(row.duration)),
                Self.quoted(row.bookTitle),
                Self.quoted(row.bookAuthor),
            ].joined(separator: separator))
        }
        return lines.joined(separator: "\r\n") + "\r\n"
    }

    /// UTF-8 with BOM: without the BOM Excel reads Cyrillic as mojibake.
    var data: Data {
        Data(("\u{FEFF}" + text).utf8)
    }

    var fileName: String {
        let title = String(localized: "csvExport.fileName", defaultValue: "История чтения")
        return "\(title) \(Self.format(exportDate, in: .current, withTime: false)).csv"
    }

    // MARK: - Formatting

    /// Always quotes, doubles inner quotes, and neutralizes text that a spreadsheet
    /// would run as a formula (=, +, -, @, tab, CR at the start).
    static func quoted(_ value: String) -> String {
        var value = value
        if let first = value.unicodeScalars.first, "=+-@\t\r".unicodeScalars.contains(first) {
            value = "'" + value
        }
        return "\"" + value.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    static func minutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int((duration / 60).rounded())
    }

    /// "2026-10-27 21:05": both Excel and Numbers recognize it as a date in any region.
    static func format(_ date: Date, in timeZone: TimeZone, withTime: Bool) -> String {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = timeZone
        let c = calendar.dateComponents([.year, .month, .day, .hour, .minute], from: date)
        let day = String(format: "%04d-%02d-%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0)
        guard withTime else { return day }
        return day + String(format: " %02d:%02d", c.hour ?? 0, c.minute ?? 0)
    }

    // MARK: - File

    private func writeTemporaryFile() throws -> URL {
        // A fresh folder per export, so repeated exports on the same day never collide.
        let folder = FileManager.default.temporaryDirectory
            .appending(path: UUID().uuidString, directoryHint: .isDirectory)
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let url = folder.appending(path: fileName, directoryHint: .notDirectory)
        try data.write(to: url, options: .atomic)
        return url
    }
}
