import UIKit

/// Assumption: book ids are UUIDs. Change the alias if the project uses another type.
typealias BookID = UUID

/// In-memory cache of book covers shared by all screens.
///
/// Main-actor isolated so a view can read an already loaded cover synchronously,
/// without a placeholder flash. Disk reads and decoding run off the main actor.
@MainActor
final class CoverCache {
    static let shared = CoverCache()

    /// `@concurrent` keeps the load off the main actor no matter who calls it.
    typealias Loader = @concurrent @Sendable (BookID) async throws -> UIImage

    private let loader: Loader
    private let images = NSCache<CacheKey, UIImage>()
    /// Loads in progress. Every caller asking for the same id awaits the same task,
    /// so one cover is never read from disk by two loads at once.
    private var inFlight: [BookID: Task<UIImage, any Error>] = [:]

    init(
        memoryLimitBytes: Int = 64 * 1024 * 1024,
        loader: @escaping Loader = { try await loadCoverFromDisk(id: $0) }
    ) {
        self.loader = loader
        images.totalCostLimit = memoryLimitBytes
    }

    /// A cover that is already in memory, or nil. Never touches the disk.
    func cachedCover(for id: BookID) -> UIImage? {
        images.object(forKey: CacheKey(id))
    }

    func cover(for id: BookID) async throws -> UIImage {
        if let image = cachedCover(for: id) { return image }
        if let loading = inFlight[id] { return try await loading.value }

        // Detached, not `Task {}`: a plain Task inherits the main actor, so the decode below
        // would run on main. The task is never cancelled: if the screen that started the load
        // goes away, other screens may still be waiting for it.
        let loading = Task.detached(priority: .userInitiated) { [loader] in
            let image = try await loader(id)
            // Decode now, off main; UIImage otherwise decodes lazily on first draw, on main.
            return image.preparingForDisplay() ?? image
        }
        // Registered before the first suspension point, so a concurrent caller finds it.
        inFlight[id] = loading
        defer { inFlight[id] = nil }

        let image = try await loading.value
        images.setObject(image, forKey: CacheKey(id), cost: Self.cost(of: image))
        return image
    }

    /// Decoded size in bytes, so the memory limit tracks real memory use.
    private static func cost(of image: UIImage) -> Int {
        guard let cgImage = image.cgImage else { return 1 }
        return cgImage.bytesPerRow * cgImage.height
    }
}

/// NSCache needs an object key; this wraps any BookID.
private nonisolated final class CacheKey: NSObject {
    let id: BookID
    init(_ id: BookID) { self.id = id }
    override var hash: Int { id.hashValue }
    override func isEqual(_ object: Any?) -> Bool {
        (object as? CacheKey)?.id == id
    }
}
```

