        if let image = CoverCache.shared.cachedCover(for: bookID) {
            Image(uiImage: image).resizable().scaledToFit()
        } else {
            Color.secondary.opacity(0.2)
                .task(id: bookID) {
                    if (try? await CoverCache.shared.cover(for: bookID)) != nil {
                        finishedLoads += 1
                    }
                }
        }
    }
