import Testing
import UIKit
@testable import Slumpy

private actor CallCounter {
    private(set) var count = 0
    func increment() -> Int { count += 1; return count }
}

private struct LoadError: Error {}

@MainActor
struct CoverCacheTests {
    @Test func concurrentRequestsLoadFromDiskOnce() async throws {
        let counter = CallCounter()
        let cache = CoverCache { _ in
            _ = await counter.increment()
            try await Task.sleep(for: .milliseconds(100))
            return UIImage()
        }
        let id = BookID()
        try await withThrowingTaskGroup(of: UIImage.self) { group in
            for _ in 0..<10 { group.addTask { try await cache.cover(for: id) } }
            for try await _ in group {}
        }
        #expect(await counter.count == 1)
        #expect(cache.cachedCover(for: id) != nil)
    }

    @Test func sequentialRequestAfterSuccessLoadsOnce() async throws {
        let counter = CallCounter()
        let cache = CoverCache { _ in
            _ = await counter.increment()
            return UIImage()
        }
        let id = BookID()
        _ = try await cache.cover(for: id)
        _ = try await cache.cover(for: id)
        #expect(await counter.count == 1)
    }

    @Test func cancellingFirstCallerDoesNotFailOthers() async throws {
        let counter = CallCounter()
        let (gate, openGate) = AsyncStream.makeStream(of: Void.self)
        let cache = CoverCache { _ in
            _ = await counter.increment()
            for await _ in gate {}          // held until the test opens the gate
            try Task.checkCancellation()    // fails if the shared load was cancelled
            return UIImage()
        }
        let id = BookID()

        let first = Task { try await cache.cover(for: id) }
        while await counter.count == 0 { await Task.yield() }  // load has started
        let second = Task { try await cache.cover(for: id) }
        await Task.yield()                                      // let `second` join the load

        first.cancel()
        openGate.finish()

        _ = try await first.value
        _ = try await second.value
        #expect(await counter.count == 1)
    }

    @Test func failedLoadIsRetried() async throws {
        let counter = CallCounter()
        let cache = CoverCache { _ in
            if await counter.increment() == 1 { throw LoadError() }
            return UIImage()
        }
        let id = BookID()
        await #expect(throws: LoadError.self) { try await cache.cover(for: id) }
        _ = try await cache.cover(for: id)
        #expect(await counter.count == 2)
    }
}
