```swift
// CoverCache.swift
import UIKit

/// Assumption: books are identified by UUID. If the id is another type, change only this line.
typealias BookID = UUID

/// In-memory cache of book covers shared by all screens.
///
/// Lives on the main actor so views can read it synchronously: a cover already in memory shows
/// on the first frame without a placeholder flash. Disk loading and decoding run off the main
/// actor. At most one disk load runs per book id; concurrent callers await the same task.
@MainActor
final class CoverCache {
    typealias Loader = @Sendable (BookID) async throws -> UIImage

    // If loadCoverFromDisk is MainActor-isolated (the default under MainActor default isolation),
    // mark it `nonisolated` or `@concurrent`, otherwise disk reads run on the main thread.
    static let shared = CoverCache { try await loadCoverFromDisk(id: $0) }

    private let loader: Loader
    private let memory = NSCache<CacheKey, UIImage>()
    private var inFlight: [BookID: Task<UIImage, any Error>] = [:]

    init(memoryLimitBytes: Int = 50 * 1024 * 1024, loader: @escaping Loader) {
        self.loader = loader
        memory.totalCostLimit = memoryLimitBytes
    }

    func cachedImage(for id: BookID) -> UIImage? {
        memory.object(forKey: CacheKey(id))
    }

    /// Waiting callers do not cancel the load: it finishes and is cached for the next screen.
    /// Failures are not cached; the next request retries.
    func image(for id: BookID) async throws -> UIImage {
        if let image = cachedImage(for: id) { return image }
        if let task = inFlight[id] { return try await task.value }

        // The task inherits the main actor, so its body cannot start before the insert below;
        // it stores the result and clears the entry with no suspension in between.
        let loader = self.loader
        let task = Task {
            defer { self.inFlight[id] = nil }
            let image = try await Self.loadAndDecode(id, using: loader)
            self.memory.setObject(image, forKey: CacheKey(id), cost: Self.cost(of: image))
            return image
        }
        inFlight[id] = task
        return try await task.value
    }

    @concurrent
    private nonisolated static func loadAndDecode(_ id: BookID, using loader: Loader) async throws -> UIImage {
        let image = try await loader(id)
        return await image.byPreparingForDisplay() ?? image
    }

    private static func cost(of image: UIImage) -> Int {
        guard let cgImage = image.cgImage else { return 0 }
        return cgImage.bytesPerRow * cgImage.height
    }
}

/// NSCache needs class keys; wraps the id with value equality.
private nonisolated final class CacheKey: NSObject {
    let id: BookID
    init(_ id: BookID) { self.id = id }
    override var hash: Int { id.hashValue }
    override func isEqual(_ object: Any?) -> Bool { (object as? CacheKey)?.id == id }
}
```

