// BookCoverView.swift
import SwiftUI

struct BookCoverView: View {
    let bookID: BookID
    @State private var loaded: (id: BookID, image: UIImage)?

    var body: some View {
        let image = loaded?.id == bookID ? loaded?.image : CoverCache.shared.cachedImage(for: bookID)
        Group {
            if let image {
                Image(uiImage: image).resizable().scaledToFill()
            } else {
                Rectangle().fill(.quaternary)
            }
        }
        .task(id: bookID) {
            // A cancelled task (bookID changed) must not overwrite the newer cover.
            guard let image = try? await CoverCache.shared.image(for: bookID), !Task.isCancelled else { return }
            loaded = (bookID, image)
        }
    }
}
