    @Test func failedLoadIsRetried() async throws {
        let counter = LoadCounter()
        let cache = CoverCache { _ in
            let attempt = await counter.increment()
            if attempt == 1 { throw CocoaError(.fileReadNoSuchFile) }
            return UIImage()
        }
        let id = BookID()
        await #expect(throws: CocoaError.self) { try await cache.image(for: id) }
        _ = try await cache.image(for: id)
        #expect(await counter.value == 2)
    }

    @Test func cancelledRequestDoesNotCancelLoad() async throws {
        let counter = LoadCounter()
        let (started, startedContinuation) = AsyncStream<Void>.makeStream()
        let (gate, gateContinuation) = AsyncStream<Void>.makeStream()
        let cache = CoverCache { _ in
            await counter.increment()
            startedContinuation.yield()
            for await _ in gate { break }
            try Task.checkCancellation()
            return UIImage()
        }
        let id = BookID()

        let first = Task { try await cache.image(for: id) }
        for await _ in started { break }
        let second = Task { try await cache.image(for: id) }
        first.cancel()
        gateContinuation.yield()

        _ = try await first.value
        _ = try await second.value
        _ = try await cache.image(for: id)
        #expect(await counter.value == 1)
    }
}

private actor LoadCounter {
    private(set) var value = 0
    @discardableResult func increment() -> Int { value += 1; return value }
}
```

## Допущения

1. **Тип идентификатора книги.** Я считаю, что это UUID. Если это не так, программисту нужно поменять одну строку `typealias BookID`.
2. **Функция `loadCoverFromDisk`.** Предполагается, что она не привязана к главному потоку. Если привязана, загрузка всё равно будет одна на книгу, но чтение с диска пойдёт в главном потоке и может притормаживать интерфейс. Как это исправить, написано в комментарии в коде.
3. **Как я понял «не грузить дважды».** Если два экрана просят обложку одновременно, загрузка будет одна. Пока обложка лежит в памяти, диск тоже больше не трогается. Но память ограничена, поэтому вытесненная обложка при следующем запросе прочитается с диска ещё раз. Держать в памяти все обложки без ограничения опаснее: при большой библиотеке система может закрыть приложение из-за нехватки памяти.
4. **Обложка книги не меняется.** Если позже появится смена обложки, в кеш нужно будет добавить сброс старой картинки. Сейчас его нет.
5. **Заглушка.** Пока обложка грузится, показывается нейтральный серый прямоугольник.
6. **Название модуля в тестах.** Я указал `Slumpy`. Если модуль называется иначе, нужно поправить строку `@testable import`.

